from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED, ZipInfo
from io import BytesIO
from lxml import etree as E
import hashlib, json, re, html

P=Path(__file__).resolve().parent
OUT=P/'r2-files'
OUT.mkdir(exist_ok=True)
source=ZipFile(P/'T2-peredacha-ID-6-files-business-R1.zip')
assert hashlib.sha256((P/'T2-peredacha-ID-6-files-business-R1.zip').read_bytes()).hexdigest()=='80c7b085aa31cf241c97b562dce5e386d8807e8d53ecbe1581c97a9d14a2f705'
changes={}

def pack_edit(data, entries):
 b=BytesIO()
 with ZipFile(BytesIO(data)) as old, ZipFile(b,'w',ZIP_DEFLATED) as new:
  for info in old.infolist(): new.writestr(info,entries.get(info.filename,old.read(info.filename)))
 return b.getvalue()

# Only transplant the artifact-tool-authored A2 text into its original cell.
# Every other OOXML byte, including print settings and cached values, stays intact.
ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
text=json.loads((P/'r2-a2-authored-text.json').read_text())['value']
xname='03-opis-peredavaemogo-komplekta.xlsx'
data=source.read(xname)
with ZipFile(BytesIO(data)) as old:
 xml=old.read('xl/worksheets/sheet1.xml').decode()
 m=re.search(r'(<c\b[^>]*\br="A2"[^>]*>)(.*?)(</c>)',xml)
 assert m and '<is>' in m[2]
 updated=xml[:m.start(2)]+'<is><t>'+html.escape(text,quote=False)+'</t></is>'+xml[m.end(2):]
 changes[xname]=[{'cell':'Опись!A2','before':''.join(E.fromstring(m[0]).itertext()),'after':text}]
 (OUT/xname).write_bytes(pack_edit(data,{'xl/worksheets/sheet1.xml':updated.encode()}))

