wn={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
for name in source.namelist():
 if name==xname: continue
 data=source.read(name)
 if name in replacements:
  with ZipFile(BytesIO(data)) as z: xml=z.read('word/document.xml')
  doc=E.fromstring(xml)
  edits=[]
  for old,new in replacements[name].items():
   hits=[]
   for p in doc.findall('.//w:p',wn):
    nodes=p.findall('.//w:t',wn)
    if ''.join(n.text or '' for n in nodes)==old: hits.append(nodes)
   assert len(hits)==1,(name,old,len(hits))
   nodes=hits[0];nodes[0].text=new
   for n in nodes[1:]: n.text=''
   edits.append({'before':old,'after':new})
  data=pack_edit(data,{'word/document.xml':E.tostring(doc,xml_declaration=True,encoding='UTF-8',standalone=True)})
  changes[name]=edits
 (OUT/name).write_bytes(data)

(P/'r2-change-log.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2))
print(json.dumps({'edited_files':{n:len(v) for n,v in changes.items()}},ensure_ascii=False))
